#!/bin/bash
# Native MAATAA Desktop (Tauri) ↔ MAATAA UI ↔ TLPS same-record smoke (macOS host).
#
#   1. Rebuilds the bundled product pages with the repo's own command
#      (`pnpm maataa:tauri:products`). This rewrites GITIGNORED build outputs only:
#      demo-dist, apps/tlps/dist, apps/tlp-film/dist, support-center-dist and
#      apps/maataa-desktop-tauri/web/products. Tracked generated preview loaders
#      are regenerated byte-identically from the current registry.
#   2. Builds the Tauri app offline/locked into ~/maataa-evidence-build (not the repo).
#   3. Launches the real native app. YOU perform the checklist with a SYNTHETIC idea
#      and answer y/n for each observation. Claims are only what you saw.
#   4. After you quit the app, records the registry's record IDs, versions and
#      events (no titles or content) and checks versions only moved forward.
# Nothing is installed or downloaded; nothing is committed.
# Output: docs/product/evidence/tauri-native-smoke-<UTC>.log
set -u
ALPHA7="$(cd "$(dirname "$0")/.." && pwd)"
BUILD_ROOT="${MAATAA_EVIDENCE_BUILD:-$HOME/maataa-evidence-build}"
STAMP="$(date -u +%Y%m%dT%H%M%SZ)"
LOG="$ALPHA7/docs/product/evidence/tauri-native-smoke-$STAMP.log"
INDEX="$HOME/Library/Application Support/in.maataa.desktop.tauri-trial/workspace-index.json"
TARGET="$BUILD_ROOT/alpha7-tauri"
mkdir -p "$BUILD_ROOT" "$(dirname "$LOG")"
log() { printf '%s\n' "$*" | tee -a "$LOG"; }
ask() { local answer; read -r -p "$1 [y/n] " answer; case "$answer" in y|Y) log "OWNER-OBSERVED yes | $1";; *) log "OWNER-OBSERVED NO  | $1";; esac; }

[ "$(uname)" = "Darwin" ] || { echo "macOS only."; exit 2; }
command -v pnpm >/dev/null || { echo "pnpm not found; not installing anything."; exit 2; }
if [ "${REUSE_BUILD:-0}" != "1" ]; then
  read -r -p "Rebuild gitignored product bundles and the Tauri app now? [y/N] " go
  [ "$go" = "y" ] || [ "$go" = "Y" ] || { echo "Stopped; nothing changed."; exit 0; }
fi

log "# Native Tauri same-record smoke $STAMP"
log "alpha7: $(git -C "$ALPHA7" --no-optional-locks rev-parse HEAD) on $(git -C "$ALPHA7" --no-optional-locks branch --show-current)"
git -C "$ALPHA7" --no-optional-locks status --porcelain > "$BUILD_ROOT/native-status-before.txt"
log "dirty paths before: $(wc -l < "$BUILD_ROOT/native-status-before.txt" | tr -d ' ')"

if [ "${REUSE_BUILD:-0}" = "1" ]; then
  log ""; log "### REUSE_BUILD=1: using the existing binary and bundles (no rebuild)"
  [ -x "$TARGET/debug/maataa-desktop-tauri" ] || { log "FAIL: no existing binary; run without REUSE_BUILD"; exit 1; }
else
  log ""; log "### pnpm maataa:tauri:products"
  ( cd "$ALPHA7" && pnpm maataa:tauri:products ) >>"$LOG" 2>&1 || { log "FAIL: product bundle build"; exit 1; }
  log "### cargo build (offline, locked, target outside the repo)"
  ( cd "$ALPHA7" && CARGO_TARGET_DIR="$TARGET" cargo build --manifest-path apps/maataa-desktop-tauri/src-tauri/Cargo.toml --locked --offline ) >>"$LOG" 2>&1 || { log "FAIL: cargo build"; exit 1; }
fi
BIN="$TARGET/debug/maataa-desktop-tauri"
log "binary: $BIN"
log "binary sha256: $(shasum -a 256 "$BIN" | cut -d' ' -f1)"
log "bundled MAATAA UI index sha256: $(shasum -a 256 "$ALPHA7/apps/maataa-desktop-tauri/web/products/maataa-ui/index.html" | cut -d' ' -f1)"
log "bundled TLPS idea-to-script page sha256: $(shasum -a 256 "$ALPHA7/apps/maataa-desktop-tauri/web/products/tlps/idea-to-script.html" | cut -d' ' -f1)"
if [ -f "$INDEX" ]; then cp "$INDEX" "$BUILD_ROOT/workspace-index-before-$STAMP.json"; log "registry backed up (outside repo) before launch"; else log "registry: none yet"; fi

cat <<'CHECK'

================ CHECKLIST (use a clearly SYNTHETIC idea) ================
 A. Desktop → TLPS icon → "Idea → Script". Enter e.g. "Synthetic smoke test" and a
    one-line made-up idea. Preview, then "Approve and save version 1".
    TLPS should say "MAATAA Desktop now lists prj:… at v1". Note the prj: ID.
 B. Desktop home: the project shows "Project record · v1" with the SAME prj: ID;
    activity shows "record v1".
 C. Click "Open in MAATAA UI · Brahmini". Brahmini Workbench shows "Project from
    MAATAA Desktop" with the same ID, Opened at v1, TLPS record v1, Desktop list v1.
 D. Click "Continue in TLPS · Idea → Script". TLPS opens with "Opened from MAATAA
    Desktop", same ID, "Up to date at v1".
 E. (Brahmini runtime is not reachable inside the packaged app; drafting is
    expected to be unavailable here. Do not work around it.)
 F. In TLPS click "Return to MAATAA Desktop": the Desktop window comes forward and
    the row still shows the same ID at v1. "Open record in TLPS" on that row opens
    TLPS on the same ID at v1.
 G. Quit the app (⌘Q). Then answer the questions below.
===========================================================================
CHECK
log ""; log "### native run (app output in $BUILD_ROOT/tauri-native-$STAMP.out)"
"$BIN" > "$BUILD_ROOT/tauri-native-$STAMP.out" 2>&1
log "app exited: $?"

ask "A: TLPS saved v1 and reported Desktop lists the prj: ID at v1"
ask "B: Desktop home showed the same prj: ID as 'Project record · v1' and activity 'record v1'"
ask "C: MAATAA UI Brahmini panel showed the same ID with TLPS record v1 and Desktop list v1"
ask "D: Continue in TLPS opened TLPS on the same ID, 'Up to date at v1'"
ask "F: Return to MAATAA Desktop brought the Desktop window forward with the same ID/version"

log ""; log "### registry after run (IDs, versions, events only)"
if [ -f "$INDEX" ]; then
  node -e '
    const idx = JSON.parse(require("fs").readFileSync(process.argv[1], "utf8"));
    console.log(`index version: ${idx.version}`);
    for (const p of idx.projects || []) if (p.record) console.log(`record ${p.record.recordId} v${p.record.recordVersion} (${p.product})`);
    const last = {}; let ok = true;
    for (const e of idx.events || []) {
      if (e.recordVersion === undefined) continue;
      console.log(`event #${e.sequence} ${e.action} ${e.projectId} v${e.recordVersion} ${e.timeBasis}`);
      if (last[e.projectId] !== undefined && e.recordVersion <= last[e.projectId]) ok = false;
      last[e.projectId] = e.recordVersion;
    }
    console.log(ok ? "record versions only moved forward: yes" : "record versions only moved forward: NO");
  ' "$INDEX" | tee -a "$LOG"
else
  log "registry file not found: no record was registered"
fi

git -C "$ALPHA7" --no-optional-locks status --porcelain > "$BUILD_ROOT/native-status-after.txt"
diff -q "$BUILD_ROOT/native-status-before.txt" "$BUILD_ROOT/native-status-after.txt" >/dev/null && TREE="unchanged" || TREE="CHANGED"
diff "$BUILD_ROOT/native-status-before.txt" "$BUILD_ROOT/native-status-after.txt" >> "$LOG"
log ""; log "alpha7 working tree (tracked + untracked status) during run: $TREE"
log "Evidence log: $LOG"
